namespace ghidra.feature.vt.gui.actions;

using ghidra.framework.plugintool;






using docking;
using docking.action;
using docking.action;

public class ProviderToggleAction : ToggleDockingAction {

    private static readonly string TOOL_BAR_GROUP = "ZGroup";
    private ComponentProviderAdapter componentProvider;

    public ProviderToggleAction( ComponentProviderAdapter provider ) : base( "Show " + provider.getTitle(), provider.getOwner(), false )
    {
        this.componentProvider = provider;
        
        setSelected( true );
        setToolBarData( new ToolBarData( provider.getIcon(), TOOL_BAR_GROUP ) );
        
        installVisibilityTracker( provider );
    }
    
    private void installVisibilityTracker( ComponentProviderAdapter provider ) {
        JComponent component = provider.getComponent();
        component.addHierarchyListener( new _Anon_HierarchyListener_1() );
    }
    
    /* @Override */
    public void actionPerformed( ActionContext context ) {
        componentProvider.setVisible( isSelected() );
    }
    

	internal class _Anon_HierarchyListener_1 : HierarchyListener
	{

            
            /* @Override */
			public void hierarchyChanged( HierarchyEvent e ) {
                long changeFlags = e.getChangeFlags();
                if ( HierarchyEvent.SHOWING_CHANGED ==
                    (changeFlags & HierarchyEvent.SHOWING_CHANGED) ) {
                    setSelected( provider.isVisible() );
                }
            }
        
	}

}
